macro_rules! deps {
    () => {
        State!();
        Outcome!();
    };
}

macro_rules! Context {
    () => {
        deps!();
        # [doc = " All information that is required to perform a dirwalk, and classify paths properly."] pub struct Context < 'a > { # [doc = " If not `None`, it will be checked before entering any directory to trigger early interruption."] # [doc = ""] # [doc = " If this flag is `true` at any point in the iteration, it will abort with an error."] pub should_interrupt : Option < & 'a AtomicBool > , # [doc = " The `git_dir` of the parent repository, after a call to [`gix_path::realpath()`]."] # [doc = ""] # [doc = " It's used to help us differentiate our own `.git` directory from nested unrelated repositories,"] # [doc = " which is needed if `core.worktree` is used to nest the `.git` directory deeper within."] pub git_dir_realpath : & 'a std :: path :: Path , # [doc = " The current working directory as returned by `gix_fs::current_dir()` to assure it respects `core.precomposeUnicode`."] # [doc = " It's used to produce the realpath of the git-dir of a repository candidate to assure it's not our own repository."] # [doc = ""] # [doc = " It is also used to assure that when the walk is for deletion, that the current working dir will not be collapsed."] pub current_dir : & 'a std :: path :: Path , # [doc = " The index to quickly understand if a file or directory is tracked or not."] # [doc = ""] # [doc = " ### Important"] # [doc = ""] # [doc = " The index must have been validated so that each entry that is considered up-to-date will have the [gix_index::entry::Flags::UPTODATE] flag"] # [doc = " set. Otherwise the index entry is not considered and a disk-access may occur which is costly."] pub index : & 'a gix_index :: State , # [doc = " A utility to lookup index entries faster, and deal with ignore-case handling."] # [doc = ""] # [doc = " Must be set if `ignore_case` is `true`, or else some entries won't be found if their case is different."] # [doc = ""] # [doc = " ### Deviation"] # [doc = ""] # [doc = " Git uses a name-based hash (for looking up entries, not directories) even when operating"] # [doc = " in case-sensitive mode. It does, however, skip the directory hash creation (for looking"] # [doc = " up directories) unless `core.ignoreCase` is enabled."] # [doc = ""] # [doc = " We only use the hashmap when available and when [`ignore_case`](Options::ignore_case) is enabled in the options."] pub ignore_case_index_lookup : Option < & 'a gix_index :: AccelerateLookup < 'a > > , # [doc = " A pathspec to use as filter - we only traverse into directories if it matches."] # [doc = " Note that the `ignore_case` setting it uses should match our [Options::ignore_case]."] # [doc = " If no such filtering is desired, pass an empty `pathspec` which will match everything."] pub pathspec : & 'a mut gix_pathspec :: Search , # [doc = " The `attributes` callback for use in [gix_pathspec::Search::pattern_matching_relative_path()], which happens when"] # [doc = " pathspecs use attributes for filtering."] # [doc = " If `pathspec` isn't empty, this function may be called if pathspecs perform attribute lookups."] pub pathspec_attributes : & 'a mut dyn FnMut (& BStr , gix_pathspec :: attributes :: glob :: pattern :: Case , bool , & mut gix_pathspec :: attributes :: search :: Outcome ,) -> bool , # [doc = " A way to query the `.gitignore` files to see if a directory or file is ignored."] # [doc = " Set to `None` to not perform any work on checking for ignored, which turns previously ignored files into untracked ones, a useful"] # [doc = " operation when trying to add ignored files to a repository."] pub excludes : Option < & 'a mut gix_worktree :: Stack > , # [doc = " Access to the object database for use with `excludes` - it's possible to access `.gitignore` files in the index if configured."] pub objects : & 'a dyn gix_object :: Find , # [doc = " If not `None`, override the traversal root that is computed and use this one instead."] # [doc = ""] # [doc = " This can be useful if the traversal root may be a file, in which case the traversal will"] # [doc = " still be returning possibly matching root entries."] # [doc = ""] # [doc = " ### Panics"] # [doc = ""] # [doc = " If the `traversal_root` is not in the `worktree_root` passed to [walk()](crate::walk())."] pub explicit_traversal_root : Option < & 'a std :: path :: Path > , }
    };
}

Context!()